'use strict';
const APPROVED='/assets/approved/';
const F_MODULES=[{name:'IAM',desc:'Identidade, organizações e permissões.',slug:'iam',i:0},{name:'Decision',desc:'Regras de negócio versionadas.',slug:'decision-engine',i:1},{name:'Workflows',desc:'Composição visual de processos.',slug:null,href:'/workflows/',i:2},{name:'AI Agents',desc:'Contexto e ferramentas para agir.',slug:null,href:'/agentes/',i:3},{name:'Data',desc:'Dados organizados por contrato.',slug:'data-store',i:4},{name:'Messaging',desc:'Canais que conectam experiências.',slug:'wpp-business',i:5}];
const F_LAYERS=[['Identidade','Quem pode acessar, em qual organização e com quais permissões.','iam'],['Dados','Fontes e documentos conectados com responsabilidades próprias.','data-store'],['Decisão','Regras de negócio legíveis e versionadas.','decision-engine'],['Orquestração','Eventos, condições e capacidades em uma jornada.','workflows'],['Canais','Conversa, vídeo e interfaces em diferentes contextos.','wpp-business']];
function moduleArt(i,cls='',label=''){return `<span class="module-art ${cls}" style="--sprite-pos:${(i/5)*100}%" role="img" aria-label="${label||F_MODULES[i]?.name||'Capacidade'}"></span>`}
function productArt(p,cls=''){const i=Math.max(0,PRODUCTS.findIndex(x=>x.slug===p.slug));return `<span class="product-art ${cls}" style="--sprite-pos:${i/6*100}%" role="img" aria-label="Composição arquitetural de ${p.name}"></span>`}
const plainArt=art;
art=function(name,cls='sculpture',alt='Composição arquitetural Catalisa'){if(name==='stack')return `<img class="${cls} approved-stack" src="${APPROVED}stack.png" alt="${alt}" loading="lazy">`;if(name==='signal')return `<img class="${cls} approved-signal" src="${APPROVED}hero.png" alt="${alt}" loading="lazy">`;const p=PRODUCTS.find(p=>p.art===name);if(p)return productArt(p,cls);return moduleArt(name==='orbit'?3:name==='document'?0:name==='modules'?2:4,cls,alt)};
blockTile=function(b){const i=b.category==='Identidade'?0:b.category==='Decisão'?1:b.category==='Dados'?4:b.category==='Comunicação'?5:b.category==='Inteligência'?3:b.category==='Documentos'?0:b.category==='Financeiro'?4:2;return `<a class="tile faithful-block" href="${blockLink(b)}"><span class="arrow">↗</span>${moduleArt(i,'',b.name)}${eyebrow(b.category)}<h3>${esc(b.name)}</h3><p>${esc(b.tagline)}</p><div class="status ${b.status.toLowerCase()}">${esc(b.status)}</div></a>`};
productCard=function(p){return `<a class="product-card faithful-product" href="/ecossistema/${p.slug}/">${productArt(p)}<div>${eyebrow(p.category)}<h3>${p.name}</h3><p>${p.title}</p><span class="text-link">Explorar ↗</span></div></a>`};
hero=function(tag,title,desc,visual=''){return `<section class="faithful-page-hero"><div class="container"><div class="page-intro">${eyebrow(tag)}<h1>${title}</h1><p class="lead">${desc}</p></div>${visual?`<div class="page-visual">${art(visual,'page-sculpture')}</div>`:''}</div></section>`};
function fSection(body,cls=''){return `<section class="faithful-section ${cls}"><div class="container">${body}</div></section>`}
function fArchitecture(){return `<div class="faithful-architecture"><div class="annotated-stack"><img class="approved-stack" src="${APPROVED}stack.png" alt="Estrutura explodida da plataforma — camadas roxas e brancas conectadas" loading="lazy"><a class="stack-label sl-identity" href="/capacidades/iam/"><strong>Identidade</strong><span>Quem participa,<br>e com que perfil.</span></a><a class="stack-label sl-data" href="/capacidades/data-store/"><strong>Dados</strong><span>O que alimenta<br>a sua operação.</span></a><a class="stack-label sl-decision" href="/capacidades/decision-engine/"><strong>Decisão</strong><span>Regras e políticas<br>que orientam o resultado.</span></a><a class="stack-label sl-channels" href="/capacidades/wpp-business/"><strong>Canais</strong><span>Onde a experiência<br>acontece.</span></a><div class="drawing-caption">COMPOSIÇÃO CONCEITUAL / CAPACIDADES CONECTADAS</div></div><div class="architecture-copy">${eyebrow('Arquitetura composable')}<h2>Capacidades<br>que se combinam.</h2><p>Uma base comum para conectar dados, decisões e experiências.</p><div class="architecture-layer-list">${F_LAYERS.map(([n,d,s],i)=>`<a href="${s==='workflows'?'/workflows/':'/capacidades/'+s+'/'}"><span>0${i+1}</span><strong>${n}</strong><p>${d}</p></a>`).join('')}</div></div></div>`}
function fWorkflow(i=1){const m=F_MODULES[i];return `<div class="faithful-workflow" data-selected-module="${i}"><div class="workflow-explanation"><b>${m.name}</b><p>${m.desc}</p>${link(m.href||'/capacidades/'+m.slug+'/','Explorar módulo')}</div><div class="workflow-drawing"><svg viewBox="0 0 700 115" preserveAspectRatio="none" aria-hidden="true"><path class="f-flow-line" d="M70 55H330M390 55H455Q480 55 490 30H620M455 55Q480 55 490 85H620"/><circle r="3" fill="#734b9c"><animateMotion dur="7s" repeatCount="indefinite" path="M70 55H330M390 55H455Q480 55 490 30H620"/></circle></svg><div class="wf-box wf-event"><i>◉</i><span>Evento</span></div><div class="wf-box wf-rules"><i>◇</i><span>Regras</span></div><div class="wf-box wf-main">${moduleArt(i,'mini')}<span>${m.name}</span></div><div class="wf-box wf-action"><i>↗</i><span>Ação</span></div><div class="wf-box wf-notification"><i>▤</i><span>Notificação</span></div></div></div>`}
function fCapabilities(){return `<div class="section-sidebar">${eyebrow('Blocos e capacidades')}<h2>A mesma base.<br>Novas possibilidades.</h2><p>Módulos e ferramentas que se conectam para compor soluções.</p>${link('/capacidades/','Ver todos os módulos')}</div><div class="capability-content"><div class="faithful-module-strip" role="tablist" aria-label="Explorar módulos da plataforma">${F_MODULES.map((m,i)=>`<button role="tab" aria-selected="${i===1}" data-fmodule="${i}">${moduleArt(i)}<strong>${m.name}</strong><span>${m.desc}</span></button>`).join('')}</div><div id="faithful-workflow-panel" role="tabpanel">${fWorkflow()}</div></div>`}
function fProductGrid(){return `<div class="section-sidebar">${eyebrow('Aplicações reais')}<h2>Construído<br>com Catalisa.</h2><p>Uma base comum.<br>Diferentes contextos.</p>${link('/ecossistema/','Ver o ecossistema')}</div><div class="faithful-ecosystem-grid">${PRODUCTS.map(p=>`<a class="ecosystem-mini" href="/ecossistema/${p.slug}/"><div class="ecosystem-art">${productArt(p)}${['banking','credit'].includes(p.slug)?`<img class="tiny-screen" src="/assets/screens/${p.slug==='banking'?'bank-desktop.jpg':'credit-queue.png'}" alt="Interface ${p.name} — captura de referência" loading="lazy">`:''}</div><div class="ecosystem-mini-info"><h3>${p.name}</h3><p>${p.title}</p><span>Explorar ↗</span></div></a>`).join('')}</div>`}
function fPerspectives(){return `<div class="section-sidebar">${eyebrow('Ideias em movimento')}<h2>Perspectivas<br>para o que vem.</h2><p>Arquitetura, composição<br>e responsabilidade.</p></div><div class="faithful-articles">${ESSAYS.slice(0,2).map((e,i)=>`<a href="/perspectivas/${e.slug}/"><div class="article-sculpture">${productArt(PRODUCTS[i===0?1:6])}</div><div>${eyebrow(e.tag)}<h3>${e.title}</h3><p>${e.desc}</p><span class="text-link">Ler artigo ↗</span></div></a>`).join('')}</div>`}
home=function(){return `<section class="faithful-home-hero"><div class="container"><div class="faithful-hero-copy">${eyebrow('Plataforma de tecnologia composable')}<h1>Dê forma ao<br>que vem depois.</h1><p>Da complexidade à construção.</p>${link('/arquitetura/','Explore a arquitetura','button outline')}</div><div class="faithful-hero-visual"><img src="${APPROVED}hero.png" alt="Fios dispersos encontram uma estrutura de planos e módulos translúcidos roxos e brancos" fetchpriority="high"><span class="hero-note top">IDEIAS<br>DADOS<br>PROCESSOS<br>PESSOAS</span><span class="hero-note bottom">ESTRUTURA<br>PARA O QUE<br>VEM DEPOIS.</span></div></div></section><section class="faithful-manifesto"><div class="container"><h2>Uma base. Infinitas composições.</h2><p>A Catalisa conecta capacidades de tecnologia para transformar dados, decisões e processos em produtos e operações.</p><span>MESMA BASE<br>NOVOS CONTEXTOS<br>MAIS POSSIBILIDADES</span></div></section>`+fSection(fArchitecture(),'architecture-section')+fSection(fCapabilities(),'sidebar-section capabilities-section')+fSection(fProductGrid(),'sidebar-section ecosystem-section')+fSection(fPerspectives(),'sidebar-section perspectives-section')};
footer=function(){return `<footer class="faithful-footer"><div class="container"><a class="logo" href="/" aria-label="Catalisa — início">catalisa<i></i></a><nav aria-label="Rodapé"><a href="/visao/">Visão</a><a href="/arquitetura/">Arquitetura</a><a href="/capacidades/">Capacidades</a><a href="/ecossistema/">Ecossistema</a><a href="/perspectivas/">Perspectivas</a></nav><strong>O próximo começa aqui.<i></i></strong><a class="footer-contact" href="/contato/">Vamos conversar ↗</a></div><div class="footer-utilities container"><span>© 2026 Catalisa · Proposta para avaliação</span><a href="/mapa/">Todas as páginas</a><a href="/interfaces/">Interfaces</a><a href="/fontes/">Fontes</a><a href="/press-kit/">Press-kit</a></div></footer>`};
vision=BASE_V1.vision;catalog=BASE_V1.catalog;studio=BASE_V1.studio;workflows=BASE_V1.workflows;agents=BASE_V1.agents;compositions=BASE_V1.compositions;essay=BASE_V1.essay;
architecture=function(){return hero('Arquitetura / Capacidades conectadas','Uma arquitetura<br>para construir.','Capacidades independentes, identidade compartilhada e contratos que organizam a composição.','stack')+fSection(fArchitecture(),'architecture-section')+fSection(`<div class="architecture-extension"><div>${eyebrow('Separação de responsabilidades')}<h2>A esteira busca.<br>O motor decide.</h2><p>Decision Platform reúne as fontes declaradas. Decision Engine avalia a política DMN publicada. A separação preserva o papel de cada capacidade.</p>${actions(link('/capacidades/decision-platform/','Veja a esteira'),link('/capacidades/decision-engine/','Veja o motor'))}</div><div class="reference-diagram">${fWorkflow(1)}</div></div>`)+fSection(fCapabilities(),'sidebar-section')+section(head('Contratos e estágios','Uma base que declara seus limites.')+rows([['Identidade comum','Usuário, organização e permissões acompanham a interação.'],['Contratos','Cada capacidade define as operações e os dados que aceita.'],['Estágio','Produção, Beta e Alpha indicam diferentes níveis de maturidade no catálogo.']])+source('https://docs.catalisa.app/blocks/'))};
ecosystem=function(){return hero('Ecossistema / Construído com Catalisa','Uma base.<br>Diferentes expressões.','Banking, crédito, saúde, advocacia, recrutamento, identidade e decisão. Explore as capacidades em cada contexto.','modules')+fSection(`<div class="product-directory">${PRODUCTS.map(p=>`<article><div class="directory-art">${productArt(p)}${['banking','credit'].includes(p.slug)?`<img class="directory-screen" src="/assets/screens/${p.slug==='banking'?'bank-desktop.jpg':'credit-queue.png'}" alt="${p.name} — interface de referência" loading="lazy">`:''}</div><div>${eyebrow(p.category)}<h2>${p.name}</h2><p>${p.description}</p>${actions(link('/ecossistema/'+p.slug+'/','Veja a composição','button outline'),link(p.source,'Fonte do produto'))}</div></article>`).join('')}</div>`)};
productPage=function(p){if(['banking','credit'].includes(p.slug))return platformPage(p);return hero('Ecossistema / Catalisa '+p.name,p.title,p.description,p.art)+fSection(`<div class="product-detail-intro"><div><h2>${p.principle}</h2><p>${p.principleText}</p>${link(p.source,'Explore o produto oficial','button outline')}</div><div class="product-detail-illustration">${productArt(p)}</div></div>`)+fSection(`<div class="product-journey"><div>${eyebrow('A jornada')}<h2>O trabalho,<br>passo a passo.</h2></div>${p.steps.map(([n,d],i)=>`<div><span>0${i+1}</span><h3>${n}</h3><p>${d}</p></div>`).join('')}</div>`)+section(head('Capacidades em contexto','O que esta solução organiza.')+rows(p.features))+section(head('Peças relacionadas','Uma composição que você pode explorar.','Seleção conceitual de capacidades relacionadas ao produto.')+`<div class="grid3">${p.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div>`)+fSection(`<div class="grid2"><div><h2>Autonomia com responsabilidade.</h2><p>${p.boundary}</p></div>${source(p.source,'Resumo baseado no conteúdo público do produto')}</div>`)};
platformPage=function(p){const bank=p.slug==='banking';return hero('Ecossistema / Catalisa '+p.name,p.title,p.description,p.art)+fSection(`<div class="platform-overview"><div><h2>${p.principle}</h2><p>${p.principleText}</p>${link('#interfaces-produto','Veja as interfaces')}</div><div class="platform-reference-screen"><img src="/assets/screens/${bank?'bank-desktop.jpg':'credit-queue.png'}" alt="${p.name} — captura de referência" loading="lazy">${bank?'<img class="platform-reference-phone" src="/assets/screens/bank-mobile.png" alt="App Banking — captura de referência" loading="lazy">':''}</div></div>`)+fSection(`<div class="product-journey"><div>${eyebrow('A jornada')}<h2>Um processo.<br>Vários estados.</h2></div>${p.steps.map(([n,d],i)=>`<div><span>0${i+1}</span><h3>${n}</h3><p>${d}</p></div>`).join('')}</div>`)+fSection(`<div id="interfaces-produto">${head('Interfaces / Material de referência','Veja as peças em contexto.','As imagens vêm do repositório indicado. Clique para ampliar e consultar as legendas.')}${gallery(p.slug)}</div>`)+fSection(`<details class="film-details"><summary>Ver sequência das interfaces em movimento <span>▶</span></summary>${filmBlock(p.slug)}</details>`)+section(head('Base relacionada','Capacidades para entender a composição.')+`<div class="grid3">${p.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div>`)+fSection(`<div class="grid2"><div><h2>O estágio faz parte da história.</h2><p>${p.boundary}</p></div>${source(p.source,'Documentação do repositório indicado pelo usuário')}</div>`)};
articleCards=function(){return `<div class="grid3 faithful-article-list">${ESSAYS.map((e,i)=>`<a class="article-card" href="/perspectivas/${e.slug}/"><div class="article-visual">${productArt(PRODUCTS[[1,6,2][i]])}</div>${eyebrow(e.tag)}<h3>${e.title}</h3><p>${e.desc}</p><span class="text-link">Ler perspectiva ↗</span></a>`).join('')}</div>`};
perspectives=function(){return hero('Perspectivas / Ideias em construção','Perspectivas<br>para o que vem.','Arquitetura, composição e responsabilidade a partir das capacidades e dos produtos da Catalisa.','modules')+section(articleCards())+fSection(`<div class="grid2"><div><h2>Conteúdo que aprofunda a base.</h2><p>O acervo atual reúne análises de mercado sobre tecnologia, agentes e interfaces conversacionais.</p>${link('https://catalisa.io/insights/','Explore o acervo oficial')}</div>${productArt(PRODUCTS[6],'large')}</div>`)};
blockPage=BASE_V1.blockPage;
function bindFaithful(){document.body.dataset.page=ROUTE.split('/')[1]||'home';document.body.classList.add('faithful-design');$$('[data-fmodule]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.fmodule);$$('[data-fmodule]').forEach(x=>x.setAttribute('aria-selected',x===b));$('#faithful-workflow-panel').innerHTML=fWorkflow(i)}));const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)$$('svg').forEach(s=>s.pauseAnimations?.());}

